input.command:
cd "C:/visual projects/reverse-kit/pipeline/_work/run_wol2/records"; SCR="C:/Users/3D6B~1/AppData/Local/Temp/claude/C--visual-projects-game/44586b9f-03e1-4b03-8523-201e45adf5a9/scratchpad"; python $SCR/g13_scan.py "$SCR" | head -8; cat > $SCR/g13_dump.py <<'EOF'
import yaml,re,sys,glob,os,collections,json
SCR=sys.argv[1]; lo,hi=int(sys.argv[2]),int(sys.argv[3])
files=[l.strip() for l in open(SCR+'/files_g13.txt',encoding='utf8') if l.strip()]
mult=collections.defaultdict(list)
for l in open(SCR+'/mult_lines.txt',encoding='utf8'):
    f,n,c=l.rstrip('\n').split(':',2); mult[f[:-3]].append((n,c.strip()))
src={}
for p in glob.glob('C:/visual projects/wol-ref/src/**/*.cs',recursive=True):
    src[os.path.basename(p)[:-3]]=p
items=[]
for f in files:
    d=yaml.safe_load(open(f,encoding='utf8'))
    for r in (d.get('rules') or [])+(d.get('catalog') or []):
        refs=r.get('source_refs') or [r.get('source_ref')]
        cls=[]
        for x in refs:
            for m in re.findall(r'([A-Za-z0-9_]+)\.cs',str(x)):
                if m not in cls: cls.append(m)
        hm=[c for c in cls if c in mult]
        if hm: items.append((f,r,hm))
for f,r,hm in items[lo:hi]:
    print('=====',r['id'],r.get('own_name') or r.get('title'))
    print('N:',json.dumps(r.get('numbers'),ensure_ascii=False))
    print('B:',r.get('behavior'))
    for c in hm:
        lines=open(src[c],encoding='utf8',errors='replace').read().split('\n')
        for i,l in enumerate(lines):
            if re.search(r'modValue|VarStatModType\.(Late)?Multiplicative|StatMod\(',l) and not re.search(r'^\s*//',l):
                print('  %s:%d: %s'%(c,i+1,l.strip()[:170]))
EOF
python $SCR/g13_dump.py "$SCR" 0 1000 > $SCR/g13_dump.txt; wc $SCR/g13_dump.txt; grep -c '=====' $SCR/g13_dump.txt

